/**
 * Array.prototype.reverse
 *
 * O que faz:
 * Inverte a ordem dos elementos *mutando* o array original.
 *
 * Exemplo:
 * inverter lista
 *
 * Impressão do resultado (saída esperada):
 * Original (mutado): [ 3, 2, 1 ]
 */

const nums = [1, 2, 3];
nums.reverse();
console.log('Original (mutado):', nums);
